TLM.f("Sancti/12-31",{"officium":"S. Silvestri Papæ et Conf.","rule":["OPapaC=Silvéstrum;","vide C4d;","Gloria","Credo","Prefatio=Nat"],"fallback":"Commune/C4d","from":{"Introitus":"Commune/C4d","Tractus":"Commune/C4d","Communio":"Commune/C4d"},"sections":{"Introitus":[{"k":"ref","la":"Ps 131,9-10"},{"k":"text","la":"Sacerdótes tui, Dómine, índuant justítiam, et sancti tui exsúltent: propter David servum tuum, non avértas fáciem Christi tui. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 131:1"},{"k":"text","la":"Meménto, Dómine, David: et omnis mansuetúdinis ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sacerdótes tui, Dómine, índuant justítiam, et sancti tui exsúltent: propter David servum tuum, non avértas fáciem Christi tui. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Gregem tuum, Pastor ætérne, placátus inténde: et, per beátum Silvéstrum Summum Pontíficem, perpétua protectióne custódi; quem totíus Ecclésiæ præstitísti esse pastórem."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Timótheum"},{"k":"ref","la":"2 Tim 4:1-8"},{"k":"text","la":"Caríssime: Testíficor coram Deo, et Jesu Christo, qui judicatúrus est vivos et mórtuos, per advéntum ipsíus et regnum ejus: prǽdica verbum, insta opportúne, importune: árgue, óbsecra, íncrepa in omni patiéntia, et doctrína. Erit enim tempus, cum sanam doctrínam non sustinébunt, sed ad sua desidéria, coacervábunt sibi magistros, pruriéntes áuribus, et a veritáte quidem audítum avértent, ad fábulas autem converténtur. Tu vero vígila, in ómnibus labóra, opus fac Evangelístæ, ministérium tuum ímple. Sóbrius esto. Ego enim jam delíbor, et tempus resolutiónis meæ instat. Bonum certámen certávi, cursum consummávi, fidem servávi. In réliquo repósita est mihi coróna justítiæ, quam reddet mihi Dóminus in illa die, justus judex: non solum autem mihi, sed et iis, qui díligunt advéntum ejus."}],"Graduale":[{"k":"ref","la":"Eccli 44:16"},{"k":"text","la":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo."},{"k":"ref","la":"Eccli 44:20"},{"k":"text","la":"Non est invéntus símilis illi, qui conserváret legem Excélsi. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 88:21"},{"k":"text","la":"Invéni David servum meum: óleo sancto meo unxi eum. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja."},{"k":"text","la":"Hic est sacérdos, quem coronávit Dóminus. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 12:35-40"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Sint lumbi vestri præcíncti, et lucernæ ardéntes in mánibus vestris, et vos símiles homínibus exspectántibus dóminum suum, quando revertátur a núptiis: ut, cum vénerit et pulsáverit, conféstim apériant ei. Beáti servi illi, quos, cum vénerit dóminus, invénerit vigilántes: amen, dico vobis, quod præcínget se, et fáciet illos discúmbere, et tránsiens ministrábit illis. Et si vénerit in secúnda vigília, et si in tértia vigília vénerit, et ita invénerit, beáti sunt servi illi. Hoc autem scitóte, quóniam, si sciret paterfamílias, qua hora fur veníret, vigiláret útique, et non síneret pérfodi domum suam. Et vos estóte paráti, quia, qua hora non putátis, Fílius hóminis véniet."}],"Offertorium":[{"k":"ref","la":"Ps 88:21-22"},{"k":"text","la":"Invéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Oblátis munéribus, quǽsumus, Dómine, Ecclésiam tuam benígnus illúmina: ut, et gregis tui profíciat ubíque succéssus, et grati fiant nómini tuo, te gubernánte, pastóres."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 24:46-47"},{"k":"text","la":"Beátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Refectióne sancta enutrítam gubérna, quǽsumus, Dómine, tuam placátus Ecclésiam: ut, poténti moderatióne dirécta, et increménta libertátis accípiat et in religiónis integritáte persístat."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro Octava Nativitatis."},{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut nos Unigéniti tui nova per carnem Natívitas líberet; quos sub peccáti jugo vetústa sérvitus tenet."},{"k":"macro","name":"Per eundem"}],"Commemoratio Secreta":[{"k":"rubric","la":"Pro Octava Nativitatis."},{"k":"text","la":"Obláta, Dómine, múnera, nova Unigéniti tui Nativitáte sanctífica: nosque a peccatórum nostrórum máculis emúnda."},{"k":"macro","name":"Per eundem"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro Octava Nativitatis."},{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut natus hódie Salvátor mundi, sicut divínæ nobis generatiónis est auctor; ita et immortalitátis sit ipse largítor:"},{"k":"macro","name":"Qui tecum"}]},"hr":{"fb21e1b462269275":{"t":"<i>Pomolimo se</i>.\nVječni Pastiru, milosno pazi svoje stado i čuvaj vječnom zaštitom po zagovoru blaženoga Silvestra pape koga si postavio za pastira čitave Crkve.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"465033a1b349c3e4":{"t":"Po prikaznim darovima, molimo, Gospodine, dobrostivo rasvijetli svoju Crkvu da i stado tvoje sve više i više napreduje i da ti ugode pastiri koje si postavio.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"48b397156b3ff99b":{"t":"<i>Pomolimo se</i>.\nVladaj, molimo, Gospodine, svojom Crkvom koja je nahranjena, na svetoj gozbi, da po tvome snažnom ravnanju zadobije porast slobode i ustraje u savršenom bogoštovlju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
